const IDEA=['U.S. Department of Education: Individuals with Disabilities Education Act (IDEA)','https://sites.ed.gov/idea/'];
const CMS_RIGHTS=['eCFR 42 CFR 483.10: resident rights in long-term care facilities','https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-G/part-483/subpart-B/section-483.10'];
